function validate(input) {
  const [{ Tweets = [] }] = input;
  const ids = new Set();
  for (const [id, content] of Tweets) {
    if (id === null) return 'Every tweet needs a tweet_id.';
    if (ids.has(id)) return `tweet_id ${id} appears twice in Tweets.`;
    ids.add(id);
    if (content === null || !/^[A-Za-z0-9! ]{0,50}$/.test(content)) return `Tweet ${id} must hold at most 50 letters, digits, "!" or spaces.`;
  }
  return null;
}

