function generate(rand, size) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!     ';
  const text = length => { let s = ''; for (let k = 0; k < length; k++) s += alphabet[Math.floor(rand() * alphabet.length)]; return s; };
  const count = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const Tweets = [];
  let id = 0;
  for (let i = 0; i < count; i++) {
    id += 1 + Math.floor(rand() * 3);
    // Small cases cluster around the 15/16 boundary; large ones spread over every allowed length.
    const length = size === 'small' ? (rand() < 0.7 ? 13 + Math.floor(rand() * 5) : Math.floor(rand() * 51)) : Math.floor(rand() * 51);
    Tweets.push([id, text(length)]);
  }
  return [{ Tweets }];
}
